static bool build_roots(Fixture*f,Pipeline*p,const SolMirRuntimeHandlerAbiLimits*limits,size_t root_count) {
    SolMirProgramRoot roots[]={
        {find(&f->ir,"newest",SOL_IR_CALLABLE_FUNCTION,0),SOL_MIR_PROGRAM_ROOT_INTERNAL_FIXTURE},
        {find(&f->ir,"distinct_roots",SOL_IR_CALLABLE_FUNCTION,0),SOL_MIR_PROGRAM_ROOT_INTERNAL_FIXTURE},
        {find(&f->ir,"one_handler",SOL_IR_CALLABLE_FUNCTION,0),SOL_MIR_PROGRAM_ROOT_INTERNAL_FIXTURE},
        {find(&f->ir,"cleanup_return",SOL_IR_CALLABLE_FUNCTION,0),SOL_MIR_PROGRAM_ROOT_INTERNAL_FIXTURE},
        {find(&f->ir,"cleanup_failure",SOL_IR_CALLABLE_FUNCTION,0),SOL_MIR_PROGRAM_ROOT_INTERNAL_FIXTURE},
    };
    if(reverse_roots)for(size_t i=0;i<sizeof roots/sizeof *roots/2;i++){SolMirProgramRoot swap=roots[i];roots[i]=roots[sizeof roots/sizeof *roots-1-i];roots[sizeof roots/sizeof *roots-1-i]=swap;}
    SolIrCallableId imports[]={find(&f->ir,"write",SOL_IR_CALLABLE_CAPABILITY,0)};
    SolMirTargetDescriptor target=sol_mir_target_wasm32();
    return root_count&&root_count<=sizeof roots/sizeof *roots&&roots[0].callable!=SOL_IR_NONE&&roots[1].callable!=SOL_IR_NONE&&roots[2].callable!=SOL_IR_NONE&&roots[3].callable!=SOL_IR_NONE&&roots[4].callable!=SOL_IR_NONE&&imports[0]!=SOL_IR_NONE&&sol_mir_concrete_program_build(&(SolMirConcreteBuildRequest){&f->ir,roots,root_count,imports,1,&target,NULL},&p->concrete,&f->d)==SOL_MIR_CONCRETE_BUILD_SUCCEEDED&&sol_mir_runtime_conventions_build(&(SolMirRuntimeConventionsBuildRequest){&p->concrete,NULL},&p->conventions,&f->d)==SOL_MIR_RUNTIME_CONVENTIONS_BUILD_SUCCEEDED&&sol_mir_runtime_values_build(&(SolMirRuntimeValuesBuildRequest){&p->conventions,NULL},&p->values,&f->d)==SOL_MIR_RUNTIME_VALUES_BUILD_SUCCEEDED&&sol_mir_runtime_cleanup_build(&(SolMirRuntimeCleanupBuildRequest){&p->conventions,&p->values,NULL},&p->cleanup,&f->d)==SOL_MIR_RUNTIME_CLEANUP_BUILD_SUCCEEDED&&sol_mir_runtime_host_abi_build(&(SolMirRuntimeHostAbiBuildRequest){&p->conventions,&p->values,&p->cleanup,NULL},&p->host,&f->d)==SOL_MIR_RUNTIME_HOST_ABI_BUILD_SUCCEEDED&&sol_mir_runtime_handler_abi_build(&(SolMirRuntimeHandlerAbiBuildRequest){&p->conventions,&p->values,&p->cleanup,&p->host,limits},&p->abi,&f->d)==SOL_MIR_RUNTIME_HANDLER_ABI_BUILD_SUCCEEDED;
}
static bool build(Fixture*f,Pipeline*p,const SolMirRuntimeHandlerAbiLimits*limits) { return build_roots(f,p,limits,5); }
static bool bytes(const SolMirRuntimeHandlerAbi*a,unsigned char **out,size_t *length) { *out=NULL;*length=0;FILE*s=tmpfile();if(!s||!sol_mir_runtime_handler_abi_render(s,a)||fflush(s)||fseek(s,0,SEEK_END))goto done;long n=ftell(s);if(n<0||(uintmax_t)n>SIZE_MAX||fseek(s,0,SEEK_SET))goto done;*out=malloc((size_t)n+1);if(!*out)goto done;*length=(size_t)n;if(fread(*out,1,*length,s)!=*length){free(*out);*out=NULL;*length=0;}else (*out)[*length]=0;done:if(s)fclose(s);return *out!=NULL; }
static void reject_render(SolMirRuntimeHandlerAbi*a) { FILE*s=tmpfile();CHECK(s!=NULL);if(!s)return;CHECK(!sol_mir_runtime_handler_abi_render(s,a));CHECK(fseek(s,0,SEEK_END)==0&&ftell(s)==0);fclose(s); }
static SolMirRuntimeHandlerDispatch dispatch(const SolMirRuntimeHandlerFramePlan*f,uint64_t root) { return (SolMirRuntimeHandlerDispatch){f->source_binding,f->source_operation,f->source_signature,root}; }
static size_t root_frame(const SolMirRuntimeHandlerAbi*a,size_t nth) { for(size_t i=0;i<a->frame_count;i++)if(a->frames[i].parent==SOL_MIR_RUNTIME_NONE&&!nth--)return i;return SOL_MIR_RUNTIME_NONE; }
static size_t child_frame(const SolMirRuntimeHandlerAbi*a,size_t parent) { for(size_t i=0;i<a->frame_count;i++)if(a->frames[i].parent==parent)return i;return SOL_MIR_RUNTIME_NONE; }
static bool enter_path(const SolMirRuntimeHandlerAbi*a,SolMirRuntimeHandlerActivationStack*s,size_t frame,uint64_t root) { size_t path[32],n=0;while(frame!=SOL_MIR_RUNTIME_NONE&&n<sizeof path/sizeof path[0]){path[n++]=frame;frame=a->frames[frame].parent;}if(frame!=SOL_MIR_RUNTIME_NONE)return false;while(n)if(!sol_mir_runtime_handler_abi_test_enter(a,s,path[--n],root,true))return false;return true; }
static bool same_stack(const SolMirRuntimeHandlerActivationStack*a,const SolMirRuntimeHandlerActivationStack*b,const SolMirRuntimeHandlerActivation*frames,const SolMirRuntimeHandlerActivation*saved) { return !memcmp(a,b,sizeof *a)&&!memcmp(frames,saved,b->count*sizeof *frames); }

static void test_activation(const SolMirRuntimeHandlerAbi*a) {
    size_t outer=root_frame(a,0),inner=child_frame(a,outer);CHECK(outer!=SOL_MIR_RUNTIME_NONE&&inner!=SOL_MIR_RUNTIME_NONE);if(outer==SOL_MIR_RUNTIME_NONE||inner==SOL_MIR_RUNTIME_NONE)return;
    SolMirRuntimeHandlerActivation storage[16];SolMirRuntimeHandlerActivationStack stack;sol_mir_runtime_handler_abi_test_stack_init(&stack,storage,16);
    CHECK(!sol_mir_runtime_handler_abi_test_enter(a,&stack,outer,1,false)&&stack.count==0);
    CHECK(enter_path(a,&stack,inner,1)&&stack.count==2&&stack.frames[1].parent==outer);
    SolMirRuntimeHandlerSelection pick;SolMirRuntimeHandlerDispatch d=dispatch(&a->frames[inner],1);
    /* All caller-owned storage, including visibility and every activation
       coordinate, is sealed before an operation can inspect it. */
    SolMirRuntimeHandlerActivationStack good=stack,forged=stack;forged.visible_count=0;CHECK(sol_mir_runtime_handler_abi_test_select(a,&forged,&d,&pick)==SOL_MIR_RUNTIME_HANDLER_SELECT_INVALID&&!memcmp(&forged,&(SolMirRuntimeHandlerActivationStack){.frames=storage,.count=2,.capacity=16,.visible_count=0,.seal=good.seal},sizeof forged));SolMirRuntimeHandlerActivation bad_storage[16];memcpy(bad_storage,storage,sizeof storage);forged=good;forged.frames=bad_storage;forged.frames[1].root=9;CHECK(sol_mir_runtime_handler_abi_test_select(a,&forged,&d,&pick)==SOL_MIR_RUNTIME_HANDLER_SELECT_INVALID&&forged.frames[1].root==9);
    CHECK(sol_mir_runtime_handler_abi_test_select(a,&stack,&d,&pick)==SOL_MIR_RUNTIME_HANDLER_SELECT_MATCH&&pick.frame==inner&&pick.active_index==1&&pick.hidden_count==1);
    CHECK(sol_mir_runtime_handler_abi_test_hide(a,&stack,&pick)&&stack.visible_count==1&&pick.hidden_count==1);
    /* An older exact frame can be selected and hidden while the inner suffix
       remains physically present but hidden.  Each selection restores only
       the visible prefix it sealed before its own hide. */
    SolMirRuntimeHandlerSelection older;
    CHECK(sol_mir_runtime_handler_abi_test_select(a,&stack,&d,&older)==SOL_MIR_RUNTIME_HANDLER_SELECT_MATCH&&older.frame==outer&&older.active_index==0&&older.hidden_count==1);
    CHECK(sol_mir_runtime_handler_abi_test_hide(a,&stack,&older)&&stack.visible_count==0&&older.hidden_count==1);
    SolMirRuntimeHandlerSelection no_match;
    CHECK(sol_mir_runtime_handler_abi_test_select(a,&stack,&d,&no_match)==SOL_MIR_RUNTIME_HANDLER_SELECT_NO_MATCH);
#define CHECK_REJECT_STACK(call) do { SolMirRuntimeHandlerActivationStack before=stack;SolMirRuntimeHandlerActivation saved[16];memcpy(saved,storage,before.count*sizeof *saved);CHECK(!(call)&&same_stack(&stack,&before,storage,saved)); } while(0)
    /* The inner transaction is blocked by the nested older transaction; an
       active selection cannot be hidden twice, and altered selections cannot
       authenticate the current hidden state. */
    CHECK_REJECT_STACK(sol_mir_runtime_handler_abi_test_restore(a,&stack,&pick,true));
    CHECK_REJECT_STACK(sol_mir_runtime_handler_abi_test_hide(a,&stack,&older));
    SolMirRuntimeHandlerSelection forged_selection=older;forged_selection.hidden_count++;
    CHECK_REJECT_STACK(sol_mir_runtime_handler_abi_test_restore(a,&stack,&forged_selection,true));
    SolMirRuntimeHandlerSelection swapped=older;swapped.active_index=pick.active_index;swapped.frame=pick.frame;
    CHECK_REJECT_STACK(sol_mir_runtime_handler_abi_test_restore(a,&stack,&swapped,true));
    CHECK(sol_mir_runtime_handler_abi_test_restore(a,&stack,&older,true)&&stack.visible_count==1&&stack.count==2);
    CHECK_REJECT_STACK(sol_mir_runtime_handler_abi_test_restore(a,&stack,&older,true));
    CHECK(sol_mir_runtime_handler_abi_test_restore(a,&stack,&pick,true)&&stack.visible_count==stack.count);
    CHECK_REJECT_STACK(sol_mir_runtime_handler_abi_test_restore(a,&stack,&pick,true));

    /* Provider failure restores the older prefix exactly as success does; the
       original inner selection then restores full visibility. */
    sol_mir_runtime_handler_abi_test_stack_init(&stack,storage,16);CHECK(enter_path(a,&stack,inner,1));
    CHECK(sol_mir_runtime_handler_abi_test_select(a,&stack,&d,&pick)==SOL_MIR_RUNTIME_HANDLER_SELECT_MATCH&&sol_mir_runtime_handler_abi_test_hide(a,&stack,&pick));
    CHECK(sol_mir_runtime_handler_abi_test_select(a,&stack,&d,&older)==SOL_MIR_RUNTIME_HANDLER_SELECT_MATCH&&sol_mir_runtime_handler_abi_test_hide(a,&stack,&older));
    CHECK(sol_mir_runtime_handler_abi_test_restore(a,&stack,&older,false)&&stack.visible_count==1);
    CHECK(sol_mir_runtime_handler_abi_test_restore(a,&stack,&pick,false)&&stack.visible_count==stack.count);

    /* Mutating either hidden suffix invalidates its sealed transaction and
       must not cause restore to change caller-owned stack storage. */
    sol_mir_runtime_handler_abi_test_stack_init(&stack,storage,16);CHECK(enter_path(a,&stack,inner,1));
    CHECK(sol_mir_runtime_handler_abi_test_select(a,&stack,&d,&pick)==SOL_MIR_RUNTIME_HANDLER_SELECT_MATCH&&sol_mir_runtime_handler_abi_test_hide(a,&stack,&pick));
    CHECK(sol_mir_runtime_handler_abi_test_select(a,&stack,&d,&older)==SOL_MIR_RUNTIME_HANDLER_SELECT_MATCH&&sol_mir_runtime_handler_abi_test_hide(a,&stack,&older));
    storage[1].root^=UINT64_C(1);
    CHECK_REJECT_STACK(sol_mir_runtime_handler_abi_test_restore(a,&stack,&older,true));
#undef CHECK_REJECT_STACK
    sol_mir_runtime_handler_abi_test_stack_init(&stack,storage,16);CHECK(enter_path(a,&stack,inner,1));
    SolMirRuntimeHandlerDispatch wrong=d;wrong.root=2;CHECK(sol_mir_runtime_handler_abi_test_select(a,&stack,&wrong,&pick)==SOL_MIR_RUNTIME_HANDLER_SELECT_NO_MATCH);wrong=d;wrong.operation.root^=1;CHECK(sol_mir_runtime_handler_abi_test_select(a,&stack,&wrong,&pick)==SOL_MIR_RUNTIME_HANDLER_SELECT_MATCH);wrong=d;wrong.operation.effects^=1;CHECK(sol_mir_runtime_handler_abi_test_select(a,&stack,&wrong,&pick)==SOL_MIR_RUNTIME_HANDLER_SELECT_NO_MATCH);wrong=d;wrong.source_binding^=1;CHECK(sol_mir_runtime_handler_abi_test_select(a,&stack,&wrong,&pick)==SOL_MIR_RUNTIME_HANDLER_SELECT_MATCH);wrong=d;wrong.signature^=1;CHECK(sol_mir_runtime_handler_abi_test_select(a,&stack,&wrong,&pick)==SOL_MIR_RUNTIME_HANDLER_SELECT_NO_MATCH);
    size_t count=stack.count;CHECK(!sol_mir_runtime_handler_abi_test_exit_marker(a,&stack,outer,a->exit_markers[a->frames[outer].exit_markers.offset].instruction)&&stack.count==count);
    CHECK(sol_mir_runtime_handler_abi_test_exit_marker(a,&stack,inner,a->exit_markers[a->frames[inner].exit_markers.offset].instruction)&&stack.count==1);
    CHECK(!sol_mir_runtime_handler_abi_test_exit_marker(a,&stack,inner,a->exit_markers[a->frames[inner].exit_markers.offset].instruction)&&stack.count==1);
    CHECK(sol_mir_runtime_handler_abi_test_exit_marker(a,&stack,outer,a->exit_markers[a->frames[outer].exit_markers.offset].instruction)&&stack.count==0);
    CHECK(enter_path(a,&stack,outer,1)&&sol_mir_runtime_handler_abi_test_exit_marker(a,&stack,outer,a->exit_markers[a->frames[outer].exit_markers.offset].instruction));
    CHECK(enter_path(a,&stack,outer,1)&&sol_mir_runtime_handler_abi_test_exit_marker(a,&stack,outer,a->exit_markers[a->frames[outer].exit_markers.offset].instruction));
}
